// Pre-generated natural-voice audio, stored on the device so lessons play offline without loading
// the neural model. Each sentence is generated by Kokoro, encoded to MP3 (~14 MB per hour) and saved
// in IndexedDB, keyed by voice + the exact spoken text. The player checks here before generating live.

import { sentences, speakable } from "./extract.js";
import { natural } from "./natural.js";
import { store } from "./store.js";

// ---------- storage ----------
let dbp = null;
function db() {
  if (dbp) { return dbp; }
  dbp = new Promise((resolve, reject) => {
    const req = indexedDB.open("hai-scholar-audio", 1);
    req.onupgradeneeded = () => {
      req.result.createObjectStore("clips"); // "voice|hash" -> Blob (audio/mpeg)
      req.result.createObjectStore("done");  // "voice|resourceId" -> { bytes, n }
    };
    req.onsuccess = () => resolve(req.result);
    req.onerror = () => reject(req.error);
  });
  return dbp;
}

async function op(storeName, mode, fn) {
  const d = await db();
  return new Promise((resolve, reject) => {
    const tx = d.transaction(storeName, mode);
    const r = fn(tx.objectStore(storeName));
    tx.oncomplete = () => resolve(r && r.result);
    tx.onerror = () => reject(tx.error);
    tx.onabort = () => reject(tx.error);
  });
}

function hash(s) {
  let h = 0x811c9dc5;
  for (let i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 0x01000193); }
  return `${(h >>> 0).toString(36)}${s.length.toString(36)}`;
}

const clipKey = (text, voice) => `${voice}|${hash(text)}`;

export async function getClip(text, voice) {
  try { return (await op("clips", "readonly", (s) => s.get(clipKey(text, voice)))) || null; } catch { return null; }
}

async function hasClip(text, voice) {
  try { return (await op("clips", "readonly", (s) => s.count(clipKey(text, voice)))) > 0; } catch { return false; }
}

// Resource ids fully generated for a voice.
export async function doneIds(voice = store.settings().naturalVoice) {
  try {
    const keys = await op("done", "readonly", (s) => s.getAllKeys());
    return new Set(keys.filter((k) => k.startsWith(`${voice}|`)).map((k) => k.slice(voice.length + 1)));
  } catch { return new Set(); }
}

export async function isDone(resId, voice = store.settings().naturalVoice) {
  try { return (await op("done", "readonly", (s) => s.count(`${voice}|${resId}`))) > 0; } catch { return false; }
}

export async function totalBytes() {
  try {
    const vals = await op("done", "readonly", (s) => s.getAll());
    return vals.reduce((n, v) => n + (v.bytes || 0), 0);
  } catch { return 0; }
}

export async function clearAll() {
  await op("clips", "readwrite", (s) => s.clear());
  await op("done", "readwrite", (s) => s.clear());
}

// ---------- generation ----------
// The exact text the player speaks for each sentence (must match player.js).
export function spokenTexts(blocks) {
  const skip = store.settings().skipCitations;
  const out = [];
  for (const b of blocks) {
    for (const t of sentences(b.text)) { out.push(speakable(t, { skipCitations: skip }) || "."); }
  }
  return [...new Set(out)];
}

class Pack extends EventTarget {
  constructor() {
    super();
    this.running = false;
    this.stopping = false;
    this.state = null; // { label, done, total, sentence, sentences, current, failed }
  }

  emit() { this.dispatchEvent(new Event("change")); }

  stop() { if (this.running) { this.stopping = true; this.emit(); } }

  // resources: list to generate; getBlocks(r) -> the same blocks the player would read for r.
  async generate(resources, getBlocks, label) {
    if (this.running) { return; }
    this.running = true;
    this.stopping = false;
    const voice = store.settings().naturalVoice;
    const done = await doneIds(voice);
    const todo = resources.filter((r) => r.kind !== "video" && !done.has(r.id));
    this.state = { label, done: 0, total: todo.length, sentence: 0, sentences: 0, current: "", failed: [], stopped: false };
    this.emit();
    try { if (navigator.storage && navigator.storage.persist) { navigator.storage.persist(); } } catch { /* unsupported */ }
    const wake = await this.wake();
    try {
      await natural.load();
      for (const r of todo) {
        if (this.stopping) { break; }
        this.state.current = r.title;
        let texts;
        try { texts = spokenTexts(await getBlocks(r)); } catch { this.state.failed.push(r); this.state.done++; this.emit(); continue; }
        this.state.sentence = 0;
        this.state.sentences = texts.length;
        this.emit();
        let bytes = 0;
        let ok = true;
        for (const t of texts) {
          if (this.stopping) { ok = false; break; }
          if (!(await hasClip(t, voice))) {
            try {
              const blob = await natural.synthBlob(t, voice, { mp3: true });
              bytes += blob.size;
              await op("clips", "readwrite", (s) => s.put(blob, clipKey(t, voice)));
            } catch {
              ok = false;
              if (natural.state !== "ready") { break; }
            }
          }
          this.state.sentence++;
          this.emit();
        }
        if (ok) {
          await op("done", "readwrite", (s) => s.put({ bytes, n: texts.length }, `${voice}|${r.id}`));
        } else if (!this.stopping) {
          this.state.failed.push(r);
        }
        if (!this.stopping) { this.state.done++; }
        this.emit();
        if (natural.state !== "ready" && !this.stopping) { throw new Error(natural.error || "Natural voice stopped working"); }
      }
    } catch (e) {
      this.state.error = String(e && e.message || e);
    } finally {
      this.state.stopped = this.stopping;
      if (wake) { wake.release().catch(() => {}); }
      this.running = false;
      this.stopping = false;
      this.emit();
    }
    return this.state;
  }

  // Generation only runs while the app is open, so keep the screen on.
  async wake() {
    try { return navigator.wakeLock ? await navigator.wakeLock.request("screen") : null; } catch { return null; }
  }
}

export const pack = new Pack();

// ---------- move audio between devices ----------
// Generate on a computer (fast), export one file, AirDrop it to the phone, import. The phone never runs the model.
// File layout: "HAIA1" + 4-byte header length + JSON header + clip bytes back to back.
const MAGIC = "HAIA1";

export async function exportAudio() {
  const d = await db();
  const entries = (name) => new Promise((resolve, reject) => {
    const out = [];
    const req = d.transaction(name).objectStore(name).openCursor();
    req.onsuccess = () => { const c = req.result; if (!c) { resolve(out); return; } out.push([c.key, c.value]); c.continue(); };
    req.onerror = () => reject(req.error);
  });
  const clips = await entries("clips");
  const done = await entries("done");
  const head = new TextEncoder().encode(JSON.stringify({ clips: clips.map(([k, b]) => [k, b.size]), done }));
  const len = new Uint8Array(4);
  new DataView(len.buffer).setUint32(0, head.length);
  return new Blob([MAGIC, len, head, ...clips.map(([, b]) => b)], { type: "application/octet-stream" });
}

export async function importAudio(file, onProgress = () => {}) {
  const magic = await file.slice(0, 5).text();
  if (magic !== MAGIC) { throw new Error("That isn't an HAI Scholar audio file"); }
  const len = new DataView(await file.slice(5, 9).arrayBuffer()).getUint32(0);
  const head = JSON.parse(await file.slice(9, 9 + len).text());
  let pos = 9 + len;
  const total = head.clips.length;
  for (let i = 0; i < total; i += 200) {
    const batch = head.clips.slice(i, i + 200).map(([k, size]) => {
      const b = file.slice(pos, pos + size, "audio/mpeg");
      pos += size;
      return [k, b];
    });
    // Read bytes before the transaction: iOS can't store a Blob that still points into a picked file.
    const bufs = await Promise.all(batch.map(async ([k, b]) => [k, new Blob([await b.arrayBuffer()], { type: "audio/mpeg" })]));
    await op("clips", "readwrite", (s) => { for (const [k, b] of bufs) { s.put(b, k); } });
    onProgress(Math.min(i + 200, total), total);
  }
  await op("done", "readwrite", (s) => { for (const [k, v] of head.done) { s.put(v, k); } });
  return { clips: total, sources: head.done.length };
}
